DO $patch$ DECLARE s text; BEGIN s:=pg_get_functiondef('public.fin_register_issued_document(jsonb,jsonb,uuid)'::regprocedure); s:=replace(s,'public.has_permission_v2(auth.uid(),''finance.documents.edit'')','(public.has_permission(auth.uid(),''finance.dashboard'') OR public.has_module_permission(auth.uid(),''finance.documents.edit'',''all''))'); EXECUTE s; END $patch$;
ALTER POLICY findoc_line_write ON public.financial_document_lines USING ((public.has_role(auth.uid(),'admin') OR public.has_permission(auth.uid(),'finance.dashboard') OR public.has_module_permission(auth.uid(),'finance.documents.edit','all')) AND public.fin_row_visible(public.fin_entity_of('financial_documents',document_id))) WITH CHECK ((public.has_role(auth.uid(),'admin') OR public.has_permission(auth.uid(),'finance.dashboard') OR public.has_module_permission(auth.uid(),'finance.documents.edit','all')) AND public.fin_row_visible(public.fin_entity_of('financial_documents',document_id)));
ALTER POLICY findoc_line_read ON public.financial_document_lines USING ((public.has_role(auth.uid(),'admin') OR public.has_permission(auth.uid(),'finance.dashboard') OR public.has_module_permission(auth.uid(),'finance.documents.view','all')) AND public.fin_row_visible(public.fin_entity_of('financial_documents',document_id)));